double simpson(FunctionPtr f, double a, double b) {
    double c = (a + b) / 2.0;
    double h3 = (b - a) / 6.0;
    return h3 * (f(a) + 4.0 * f(c) + f(b));
}

double adaptive_simpson(FunctionPtr f, double a, double b, double precision) {
    double c = (a + b) / 2.0;
    double S_ab = simpson(f, a, b);
    double S_ac = simpson(f, a, c);
    double S_cb = simpson(f, c, b);
    double error = std::abs(S_ab - (S_ac + S_cb)) / 15.0;

    if (error <= precision) {
        return S_ac + S_cb + (S_ac + S_cb - S_ab) / 15.0;
    } else {
        return adaptive_simpson(f, a, c, precision / 2.0) +
               adaptive_simpson(f, c, b, precision / 2.0);
    }
}

